apiVersion: apprafter.io/v1alpha1
kind: Application
metadata: {
    name:      "billing-api"
    namespace: "prod"
}

spec: {
    base: {
        image:    "ghcr.io/me/billing:v1.4.2"
        replicas: 3

        expose: {
            port:    8080
            public:  true
            network: "public"
        }

        needs: {
            pg: {size: "small"}
        }

        env: {
            DATABASE_URL: from: claim.pg.uri
            LOG_LEVEL:    "info"
        }
    }

    environments: {
        dev:  base & {replicas: 1, expose: network: "vpn"}
        prod: base & {replicas: 3}
    }
}
